'use strict';

// MODULES //

var anchorPositions = require( '@stdlib/plot/vega/base/anchor-positions' );
var anchorFrames = require( '@stdlib/plot/vega/base/anchor-reference-frames' );
var verticalBaselines = require( '@stdlib/plot/vega/base/vertical-baselines' );
var textAlignments = require( '@stdlib/plot/vega/base/text-alignments' );
var fontStyles = require( '@stdlib/plot/vega/base/font-styles' );
var fontWeights = require( '@stdlib/plot/vega/base/font-weights' );
var orientations = require( '@stdlib/plot/vega/title/orientations' );


// MAIN //

/**
* Returns an editor configuration for title properties.
*
* @returns {Object} configuration
*
* @example
* var o = config();
* // returns {...}
*/
function config() {
	return {
		'align': {
			'description': 'horizontal title and subtitle text alignment',
			'property': 'align',
			'default': 'center',
			'type': 'oneOf',
			'values': textAlignments()
		},
		'anchor': {
			'description': 'anchor position for placing title and subtitle',
			'property': 'anchor',
			'default': 'middle',
			'type': 'oneOf',
			'values': anchorPositions()
		},
		'angle': {
			'description': 'angle of the title and subtitle text',
			'property': 'angle',
			'default': 0,
			'type': 'number',
			'units': 'degrees',
			'min': -360,
			'max': 360
		},
		'aria': {
			'description': 'boolean indicating whether to include ARIA attributes in SVG output',
			'property': 'aria',
			'default': true,
			'type': 'boolean'
		},
		'baseline': {
			'description': 'vertical baseline of title and subtitle text',
			'property': 'baseline',
			'default': 'alphabetic',
			'type': 'oneOf',
			'values': verticalBaselines()
		},
		'color': {
			'description': 'color of title text',
			'property': 'color',
			'default': '#000',
			'type': 'color'
		},
		'dx': {
			'description': 'horizontal offset added to the title and subtitle x-coordinate',
			'property': 'dx',
			'default': 0,
			'type': 'number',
			'units': 'px'
		},
		'dy': {
			'description': 'vertical offset added to the title and subtitle y-coordinate',
			'property': 'dy',
			'default': 0,
			'type': 'number',
			'units': 'px'
		},
		'font': {
			'description': 'font name of title text',
			'property': 'font',
			'default': 'sans-serif',
			'type': 'string'
		},
		'fontSize': {
			'description': 'font size of title text',
			'property': 'fontSize',
			'default': 11,
			'type': 'number',
			'min': 0,
			'step': 1,
			'units': 'px'
		},
		'fontStyle': {
			'description': 'font style of title text',
			'property': 'fontStyle',
			'default': 'normal',
			'type': 'oneOf',
			'values': fontStyles()
		},
		'fontWeight': {
			'description': 'font weight of title text',
			'property': 'fontWeight',
			'default': 'normal',
			'type': 'oneOf',
			'values': fontWeights()
		},
		'frame': {
			'description': 'reference frame for the anchor position',
			'property': 'frame',
			'default': 'bounds',
			'type': 'oneOf',
			'values': anchorFrames()
		},
		'limit': {
			'description': 'maximum allowed length of title and subtitle text',
			'property': 'limit',
			'default': 10000,
			'type': 'number',
			'min': 0,
			'step': 1,
			'units': 'px'
		},
		'lineHeight': {
			'description': 'line height for multi-line title text',
			'property': 'lineHeight',
			'default': 1,
			'type': 'number',
			'min': 0
		},
		'offset': {
			'description': 'orthogonal offset by which to displace the title from its position along the edge of the visualization',
			'property': 'offset',
			'default': 0,
			'type': 'number',
			'units': 'px'
		},
		'orient': {
			'description': 'title and subtitle orientation relative to the visualization',
			'property': 'orient',
			'default': 'top',
			'type': 'oneOf',
			'values': orientations()
		},
		'subtitle': {
			'description': 'subtitle text',
			'property': 'subtitle',
			'default': '',
			'type': 'string'
		},
		'subtitleColor': {
			'description': 'color of subtitle text',
			'property': 'subtitleColor',
			'default': '#000',
			'type': 'color'
		},
		'subtitleFont': {
			'description': 'font name of subtitle text',
			'property': 'subtitleFont',
			'default': 'sans-serif',
			'type': 'string'
		},
		'subtitleFontSize': {
			'description': 'font size of subtitle text',
			'property': 'subtitleFontSize',
			'default': 11,
			'type': 'number',
			'min': 0,
			'step': 1,
			'units': 'px'
		},
		'subtitleFontStyle': {
			'description': 'font style of subtitle text',
			'property': 'subtitleFontStyle',
			'default': 'normal',
			'type': 'oneOf',
			'values': fontStyles()
		},
		'subtitleFontWeight': {
			'description': 'font weight of subtitle text',
			'property': 'subtitleFontWeight',
			'default': 'normal',
			'type': 'oneOf',
			'values': fontWeights()
		},
		'subtitleLineHeight': {
			'description': 'line height for multi-line subtitle text',
			'property': 'subtitleLineHeight',
			'default': 1,
			'type': 'number',
			'min': 0
		},
		'subtitlePadding': {
			'description': 'padding between title and subtitle text',
			'property': 'subtitlePadding',
			'default': 0,
			'type': 'number',
			'units': 'px'
		},
		'text': {
			'description': 'title text',
			'property': 'text',
			'default': '',
			'type': 'string'
		},
		'zindex': {
			'description': 'integer z-index indicating the layering of a title group relative to other axis, mark, and legend groups',
			'property': 'zindex',
			'default': 0,
			'type': 'number',
			'step': 1
		}
	};
}


// EXPORTS //

module.exports = config;
